        new Dictionary<ProjectileTrailChoice, ProjectileTrailFamily?>
        {
            [new(ProjectileTrailFamilyGroup.Uncharged, SamusBeamCombination.Power)] = ProjectileTrailFamily.UnchargedDefault,
